const f=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Riga',year:'numeric',month:'2-digit',day:'2-digit'});
const [ty,tm,td]=f.format(new Date()).split('-').map(Number);
const today=new Date(Date.UTC(ty,tm-1,td));
const lv=d=>String(d.getUTCDate()).padStart(2,'0')+'.'+String(d.getUTCMonth()+1).padStart(2,'0')+'.'+d.getUTCFullYear()+'.';
const todayStr=lv(today);
const parseLV=s=>{const p=String(s==null?'':s).trim().split('.');return (p.length>=3&&p[0]&&p[1]&&p[2])?new Date(Date.UTC(+p[2],+p[1]-1,+p[0])):null;};
const out=[];
for(const it of $input.all()){
  const r=it.json;
  const due=parseLV(r['Apmaksas termiņš']);
  if(!due)continue;
  const dp=Math.round((today-due)/864e5);
  if(dp<5||dp>=7)continue;
  if(String(r['Brīdināts pirms apturēšanas']||'').trim()!=='')continue;
  const fullName=String(r['Klienta vārds']||'').trim();
  out.push({json:{name:fullName,fname:fullName.split(' ')[0]||fullName,email:String(r['E-pasts']||'').trim(),invoice_no:String(r['Rēķina Nr.']||'').trim(),amount:Number(r['Likme (EUR/mēn)']||0).toFixed(2).replace('.',','),due_date:lv(due),suspend_date:lv(new Date(due.getTime()+7*864e5)),days_past:dp,todayStr}});
}
return out;
